 if(request.method==="OPTIONS")return new Response(null,{status:204,headers:cors});
 if(request.method!=="POST")return json({error:"POST required."},405);
 if(!env.GEMINI_API_KEY)return json({error:"Gemini API key is not configured in Cloudflare."},503);
 let payload;try{const raw=await request.text();if(raw.length>60000)return json({error:"Chat request is too large."},413);payload=JSON.parse(raw)}catch{return json({error:"Invalid chat request."},400)}
