function proxyParseYahoo(raw){const r=raw?.chart?.result?.[0],q=r?.indicators?.quote?.[0],ts=r?.timestamp||[];if(!r||!q)return[];return ts.map((t,i)=>{const o=q.open?.[i],h=q.high?.[i],l=q.low?.[i],c=q.close?.[i];return [o,h,l,c].every(x=>Number.isFinite(Number(x)))?{time:Number(t),open:Number(o),high:Number(h),low:Number(l),close:Number(c),volume:Number(q.volume?.[i]||0)}:null}).filter(Boolean).sort((a,b)=>a.time-b.time);}
function proxyResample4h(bars){const groups=new Map();for(const b of bars){const t=Math.floor(b.time/14400)*14400,g=groups.get(t);if(!g)groups.set(t,{time:t,open:b.open,high:b.high,low:b.low,close:b.close,volume:b.volume||0});else{g.high=Math.max(g.high,b.high);g.low=Math.min(g.low,b.low);g.close=b.close;g.volume+=(b.volume||0)}}return [...groups.values()].sort((a,b)=>a.time-b.time);}
async function proxyFetchYahoo(sym,tf){const y=YAHOO_SYMBOLS[sym];if(!y)throw Error("Yahoo symbol mapping missing");const interval=tf==="4h"?"1h":tf==="1h"?"60m":tf;const range=tf==="1d"?"1y":tf==="1h"||tf==="4h"?"1mo":"5d";const path="/v8/finance/chart/"+encodeURIComponent(y)+"?interval="+interval+"&range="+range+"&includePrePost=false";let last="";for(const host of ["query1.finance.yahoo.com","query2.finance.yahoo.com"]){try{const r=await fetch("https://"+host+path,{headers:{Accept:"application/json"},signal:AbortSignal.timeout(7000)});if(!r.ok)throw Error("Yahoo "+r.status);const raw=await r.json(),bars=proxyCleanBars(proxyParseYahoo(raw));const out=tf==="4h"?proxyCleanBars(proxyResample4h(bars)):bars;if(proxyValidBars(out,tf))return {source:"Yahoo Finance chart (free fallback)",bars:out};last="Yahoo returned insufficient candles";}catch(e){last=String(e?.message||e)}}throw Error(last||"Yahoo chart feed failed");}
async function proxyFetchBinance(sym,tf){const map={BTCUSD:"BTCUSDT",ETHUSD:"ETHUSDT",XRPUSD:"XRPUSDT"},interval=tf==="1h"?"1h":tf==="4h"?"4h":tf==="1d"?"1d":tf;if(!map[sym])throw Error("Binance fallback only supports crypto");const r=await fetch("https://api.binance.com/api/v3/klines?symbol="+map[sym]+"&interval="+interval+"&limit=180",{headers:{Accept:"application/json"},signal:AbortSignal.timeout(7000)});if(!r.ok)throw Error("Binance "+r.status);const a=await r.json(),bars=proxyCleanBars(a.map(x=>({time:Math.floor(Number(x[0])/1000),open:Number(x[1]),high:Number(x[2]),low:Number(x[3]),close:Number(x[4]),volume:Number(x[5])})));if(!proxyValidBars(bars,tf))throw Error("Binance insufficient candles");return {source:"Binance public klines (USDT≈USD)",bars};}
async function handleMarketCandles(request){const u=new URL(request.url),sym=u.searchParams.get("symbol")||"",tf=u.searchParams.get("interval")||"5m";if(!SCAN_SYMBOLS.has(sym)||!["1m","5m","15m","30m","1h","4h","1d"].includes(tf))return Response.json({error:"Unsupported scanner symbol or timeframe"},{status:400});const key=sym+"|"+tf,cached=CANDLE_CACHE.get(key);if(cached&&Date.now()-cached.at<25000)return Response.json(cached.data,{headers:{"Cache-Control":"public, max-age=15"}});const errors=[];try{const r=await fetch("https://biquote.io/api/"+encodeURIComponent(sym)+"/ohlc?interval="+tf+"&limit=180",{headers:{Accept:"application/json"},signal:AbortSignal.timeout(7000)});if(!r.ok)throw Error("BiQuote HTTP "+r.status);const bars=proxyCleanBars(proxyParseBiquote(await r.json()));if(!proxyValidBars(bars,tf))throw Error("BiQuote insufficient/invalid candles");const data={symbol:sym,interval:tf,source:"BiQuote",bars};CANDLE_CACHE.set(key,{at:Date.now(),data});return Response.json(data,{headers:{"Cache-Control":"public, max-age=15"}})}catch(e){errors.push(String(e?.message||e))}
try{const data=await proxyFetchYahoo(sym,tf);data.symbol=sym;data.interval=tf;CANDLE_CACHE.set(key,{at:Date.now(),data});return Response.json(data,{headers:{"Cache-Control":"public, max-age=15"}})}catch(e){errors.push(String(e?.message||e))}
if(["BTCUSD","ETHUSD","XRPUSD"].includes(sym)){try{const data=await proxyFetchBinance(sym,tf);data.symbol=sym;data.interval=tf;CANDLE_CACHE.set(key,{at:Date.now(),data});return Response.json(data,{headers:{"Cache-Control":"public, max-age=15"}})}catch(e){errors.push(String(e?.message||e))}}
return Response.json({symbol:sym,interval:tf,error:"All free candle providers failed",errors},{status:502,headers:{"Cache-Control":"no-store"}});}

// Read-only MT5 signal feed. Uses the same 16-symbol scanner universe and SMC/ICT engine.
let mt5SignalCache=null,mt5SignalCacheAt=0,mt5SignalInFlight=null;
async function handleMT5Signals(){
 if(mt5SignalCache&&Date.now()-mt5SignalCacheAt<25000)return Response.json(mt5SignalCache,{headers:{"Cache-Control":"no-store"}});
 if(mt5SignalInFlight)return Response.json(await mt5SignalInFlight,{headers:{"Cache-Control":"no-store"}});
 mt5SignalInFlight=(async()=>{const symbols=[...SCAN_SYMBOLS],timeframes=["1m","5m","15m"],results=[];
  for(let offset=0;offset<symbols.length;offset+=4){const batch=await Promise.all(symbols.slice(offset,offset+4).map(async symbol=>{const loaded=await Promise.all(timeframes.map(async interval=>{try{const res=await handleMarketCandles(new Request("https://internal/api/market-candles?symbol="+encodeURIComponent(symbol)+"&interval="+interval)),p=await res.json();return [interval,res.ok&&!p.error?sigCandles(p.bars):[]]}catch{return [interval,[]]}}));const candles=Object.fromEntries(loaded);let result;try{result=sigSMC(symbol,candles)}catch(e){result={symbol,direction:"WAIT",status:"FEED UNAVAILABLE",planReady:false,progress:0,stages:[],reason:String(e?.message||e)}}return {...result,feedAvailable:result.status!=="FEED UNAVAILABLE",generatedAt:Math.floor(Date.now()/1000)}}));results.push(...batch)}
  return {ok:true,provider:"Free multi-provider candle scanner",symbols:results.length,generatedAt:Math.floor(Date.now()/1000),timeframes,results}
 })();
 try{const data=await mt5SignalInFlight;mt5SignalCache=data;mt5SignalCacheAt=Date.now();return Response.json(data,{headers:{"Cache-Control":"no-store"}})}finally{mt5SignalInFlight=null}
}

async function handleCandles(request) { const u=new URL(request.url); const symbol=u.searchParams.get('symbol')||''; const interval=u.searchParams.get('interval')||'5m'; const limit=Math.min(500,Math.max(10,Number(u.searchParams.get('limit')||250))); if(!ALLOWED_PAIRS.has(symbol)) return new Response(JSON.stringify({error:'Symbol not supported'}),{status:400,headers:{'Content-Type':'application/json'}}); const allowedIntervals=new Set(['1m','5m','15m','30m','1h','4h','1d']); if(!allowedIntervals.has(interval)) return new Response(JSON.stringify({error:'Timeframe not supported'}),{status:400,headers:{'Content-Type':'application/json'}}); try { const upstream=await fetch('https://biquote.io/api/'+encodeURIComponent(symbol)+'/ohlc?interval='+encodeURIComponent(interval)+'&limit='+limit,{headers:{'Accept':'application/json'},signal:AbortSignal.timeout(12000)}); const body=await upstream.text(); return new Response(body,{status:upstream.status,headers:{'Content-Type':upstream.headers.get('content-type')||'application/json','Cache-Control':'no-store'}}); } catch(e) {return new Response(JSON.stringify({error:'Candle data provider could not be reached',detail:String(e.message||e)}),{status:502,headers:{'Content-Type':'application/json'}})} }

const CTRADER_REDIRECT_URI = "https://analyzer-pro.fx77.workers.dev/api/ctrader/callback";
const CT_KV_KEY = "ctrader:oauth";
function ctVarint(n){let x=BigInt(n),a=[];while(x>127n){a.push(Number(x&127n)|128);x>>=7n}a.push(Number(x));return a}
function ctFieldString(no,s){const b=new TextEncoder().encode(String(s));return Uint8Array.from([...ctVarint((no<<3)|2),...ctVarint(b.length),...b])}
function ctFieldInt(no,n){return Uint8Array.from([...ctVarint(no<<3),...ctVarint(n)])}
function ctJoin(...parts){const n=parts.reduce((s,p)=>s+p.length,0),o=new Uint8Array(n);let at=0;for(const p of parts){o.set(p,at);at+=p.length}return o}
function ctEnvelope(type,payload){const body=ctJoin(ctFieldInt(1,type),Uint8Array.from([18,...ctVarint(payload.length)]),payload);const h=new Uint8Array(4);new DataView(h.buffer).setUint32(0,body.length,false);return ctJoin(h,body)}
function ctReadVar(b,p){let v=0n,s=0n;while(p.i<b.length){const x=b[p.i++];v|=BigInt(x&127)<<s;if(!(x&128))return v;s+=7n;if(s>70n)throw Error("Invalid protobuf varint")}throw Error("Truncated protobuf varint")}
function ctParseFields(b){const out=[];const p={i:0};while(p.i<b.length){const tag=Number(ctReadVar(b,p)),no=tag>>3,w=tag&7;if(w===0)out.push({no,w,v:ctReadVar(b,p)});else if(w===2){const n=Number(ctReadVar(b,p));if(n<0||p.i+n>b.length)throw Error("Invalid protobuf length");out.push({no,w,v:b.slice(p.i,p.i+n)});p.i+=n}else if(w===1){out.push({no,w,v:b.slice(p.i,p.i+8)});p.i+=8}else if(w===5){out.push({no,w,v:b.slice(p.i,p.i+4)});p.i+=4}else throw Error("Unsupported protobuf wire type")}return out}
function ctDecodeEnvelope(b){const f=ctParseFields(b);return {type:Number(f.find(x=>x.no===1)?.v||0n),payload:f.find(x=>x.no===2)?.v||new Uint8Array()}}
function ctDecodeAccounts(b){return ctParseFields(b).filter(x=>x.no===4&&x.w===2).map(x=>{const f=ctParseFields(x.v),get=n=>f.find(y=>y.no===n)?.v;return {accountId:String(get(1)||""),isLive:Boolean(get(2)||0),login:get(3)?String(get(3)):"",broker:f.find(y=>y.no===6)?.v?new TextDecoder().decode(f.find(y=>y.no===6).v):""}})}
async function ctSocketExchange(payloads,expected,host="live1.p.ctrader.com"){
 const socket=connect({hostname:host,port:5035},{secureTransport:"on"});await socket.opened;
 const writer=socket.writable.getWriter(),reader=socket.readable.getReader();let buf=new Uint8Array(0);
 async function exact(n){while(buf.length<n){const r=await reader.read();if(r.done)throw Error("cTrader closed the connection");buf=ctJoin(buf,new Uint8Array(r.value))}const out=buf.slice(0,n);buf=buf.slice(n);return out}
 async function receive(){const h=await exact(4),n=new DataView(h.buffer,h.byteOffset,4).getUint32(0,false);if(!n||n>1048576)throw Error("Invalid cTrader frame");return ctDecodeEnvelope(await exact(n))}
 try{for(const item of payloads){await writer.write(ctEnvelope(item.type,item.payload));let got=null;for(let i=0;i<6;i++){const r=await receive();if(r.type===2142){const err=ctParseFields(r.payload),code=err.find(x=>x.no===3),desc=err.find(x=>x.no===4);throw Error("cTrader "+(code?new TextDecoder().decode(code.v):"error")+(desc?": "+new TextDecoder().decode(desc.v):""))}if(r.type===item.expected){got=r;break}}if(!got)throw Error("cTrader response "+item.expected+" was not received");if(item.type===2149)return {accounts:ctDecodeAccounts(got.payload)};if(item.type===2102)return {authorized:true,accountId:String(ctParseFields(got.payload).find(x=>x.no===2)?.v||"")}}
 return {ok:true}}finally{try{await writer.close()}catch{}try{await reader.cancel()}catch{}try{socket.close()}catch{}}
}
async function ctGetToken(env){let token=await env.CTRADER_KV.get(CT_KV_KEY,"json");if(!token?.refreshToken)throw Error("cTrader account has not been authorized yet");if(Number(token.expiresAt||0)<Date.now()+120000){const u=new URL("https://openapi.ctrader.com/apps/token");u.searchParams.set("grant_type","refresh_token");u.searchParams.set("refresh_token",token.refreshToken);u.searchParams.set("client_id",env.CTRADER_CLIENT_ID);u.searchParams.set("client_secret",env.CTRADER_CLIENT_SECRET);const r=await fetch(u,{method:"POST",headers:{Accept:"application/json"}});const j=await r.json();if(!r.ok||j.errorCode||!j.accessToken)throw Error(j.description||j.errorCode||"cTrader token refresh failed");token={accessToken:j.accessToken,refreshToken:j.refreshToken,expiresAt:Date.now()+Number(j.expiresIn||2628000)*1000,permissionScope:token.permissionScope};await env.CTRADER_KV.put(CT_KV_KEY,JSON.stringify(token))}return token}
async function ctListAccounts(env){const t=await ctGetToken(env);const app=ctJoin(ctFieldString(2,env.CTRADER_CLIENT_ID),ctFieldString(3,env.CTRADER_CLIENT_SECRET));const list=ctFieldString(2,t.accessToken);return await ctSocketExchange([{type:2100,expected:2101,payload:app},{type:2149,expected:2150,payload:list}])}
async function ctAuthorizeAccount(env,accountId){const t=await ctGetToken(env);const app=ctJoin(ctFieldString(2,env.CTRADER_CLIENT_ID),ctFieldString(3,env.CTRADER_CLIENT_SECRET));const list=ctFieldString(2,t.accessToken);const id=ctFieldInt(2,BigInt(accountId));const auth=ctJoin(ctFieldInt(2,BigInt(accountId)),ctFieldString(3,t.accessToken));const info=await ctListAccounts(env);const account=info.accounts.find(a=>a.accountId===String(accountId));if(!account)throw Error("Selected cTrader account was not granted to this application");const host=account.isLive?"live1.p.ctrader.com":"demo1.p.ctrader.com";const result=await ctSocketExchange([{type:2100,expected:2101,payload:app},{type:2102,expected:2103,payload:auth}],host);return {authorized:true,account:{accountId:account.accountId,isLive:account.isLive,login:account.login,broker:account.broker}}}
function ctPage(title,body){return new Response('<!doctype html><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title><style>body{background:#08111d;color:#eef5ff;font:16px system-ui;padding:24px;max-width:560px;margin:auto}section{background:#142139;border:1px solid #345071;border-radius:16px;padding:18px;margin:12px 0}button{background:#79b5ff;color:#071322;border:0;border-radius:10px;padding:12px 16px;font-weight:800;width:100%}small{color:#aabbd1}</style><h2>Analyzer Pro · cTrader</h2>'+body,{headers:{"Content-Type":"text/html; charset=utf-8","Cache-Control":"no-store"}})}
async function handleCTrader(request,env){
 const u=new URL(request.url),p=u.pathname;
 if(p==="/api/ctrader/connect"){if(!env.CTRADER_CLIENT_ID||!env.CTRADER_CLIENT_SECRET||!env.CTRADER_KV)return ctPage("cTrader setup","<section>cTrader configuration is incomplete.</section>");const state=crypto.randomUUID();await env.CTRADER_KV.put("ctrader:state:"+state,"1",{expirationTtl:600});const a=new URL("https://id.ctrader.com/my/settings/openapi/grantingaccess/");a.searchParams.set("client_id",env.CTRADER_CLIENT_ID);a.searchParams.set("redirect_uri",CTRADER_REDIRECT_URI);a.searchParams.set("scope","trading");a.searchParams.set("product","web");a.searchParams.set("state",state);return Response.redirect(a.toString(),302)}
 if(p==="/api/ctrader/callback"){const code=u.searchParams.get("code"),state=u.searchParams.get("state");if(!code||!state||!await env.CTRADER_KV.get("ctrader:state:"+state))return ctPage("Authorization failed","<section>Authorization state expired or did not match. <a href='/api/ctrader/connect'>Try again</a>.</section>");await env.CTRADER_KV.delete("ctrader:state:"+state);const turl=new URL("https://openapi.ctrader.com/apps/token");turl.searchParams.set("grant_type","authorization_code");turl.searchParams.set("code",code);turl.searchParams.set("redirect_uri",CTRADER_REDIRECT_URI);turl.searchParams.set("client_id",env.CTRADER_CLIENT_ID);turl.searchParams.set("client_secret",env.CTRADER_CLIENT_SECRET);const tr=await fetch(turl,{headers:{Accept:"application/json"}}),j=await tr.json();if(!tr.ok||j.errorCode||!j.accessToken)return ctPage("Authorization failed","<section>"+String(j.description||j.errorCode||"Token exchange failed").replace(/[<>&]/g,"")+"</section>");await env.CTRADER_KV.put(CT_KV_KEY,JSON.stringify({accessToken:j.accessToken,refreshToken:j.refreshToken,expiresAt:Date.now()+Number(j.expiresIn||2628000)*1000,permissionScope:"trading"}));try{const a=await ctListAccounts(env);const rows=a.accounts.map(x=>'<section><b>'+String(x.broker||"cTrader broker").replace(/[<>&]/g,"")+'</b><p>'+ (x.isLive?"LIVE":"DEMO")+' account · '+x.accountId+(x.login?" · Login "+x.login:"")+'</p><button onclick="choose(\''+x.accountId+'\')">Authorize this account</button></section>').join("");return ctPage("Choose cTrader account",'<p>cTrader authorization received. Choose the account to connect to Analyzer Pro.</p>'+ (rows||"<section>No accounts were returned. Re-authorize and grant access to at least one account.</section>")+'<p id="status"></p><script>async function choose(id){let s=document.getElementById("status");s.textContent="Connecting…";try{let r=await fetch("/api/ctrader/authorize",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({accountId:id})});let j=await r.json();if(!r.ok)throw Error(j.error||"Connection failed");s.textContent="CONNECTED · "+(j.account.isLive?"LIVE":"DEMO")+" · "+j.account.accountId}catch(e){s.textContent=e.message}}</script>')}catch(e){return ctPage("Account connection pending","<section>Authorization was saved, but account discovery failed: "+String(e.message).replace(/[<>&]/g,"")+"</section><p><a href='/api/ctrader/accounts'>Retry account discovery</a></p>")}}
 if(p==="/api/ctrader/health"){try{const payload=ctJoin(ctFieldString(2,env.CTRADER_CLIENT_ID),ctFieldString(3,env.CTRADER_CLIENT_SECRET));await ctSocketExchange([{type:2100,expected:2101,payload}]);return Response.json({ok:true,tcp:true,applicationAuthorized:true},{headers:{"Cache-Control":"no-store"}})}catch(e){return Response.json({ok:false,tcp:false,error:String(e.message||e)},{status:502,headers:{"Cache-Control":"no-store"}})}}
 if(p==="/api/ctrader/status"){const t=await env.CTRADER_KV.get(CT_KV_KEY,"json");const a=await env.CTRADER_KV.get("ctrader:selected","json");return Response.json({configured:!!(env.CTRADER_CLIENT_ID&&env.CTRADER_CLIENT_SECRET&&env.CTRADER_KV),authorized:!!t?.refreshToken,account:a||null,scope:t?.permissionScope||null},{headers:{"Cache-Control":"no-store"}})}
 if(p==="/api/ctrader/accounts"){try{return Response.json(await ctListAccounts(env),{headers:{"Cache-Control":"no-store"}})}catch(e){return Response.json({error:String(e.message||e)},{status:400})}}
 if(p==="/api/ctrader/authorize"&&request.method==="POST"){try{const b=await request.json(),result=await ctAuthorizeAccount(env,String(b.accountId||""));await env.CTRADER_KV.put("ctrader:selected",JSON.stringify(result.account));return Response.json(result,{headers:{"Cache-Control":"no-store"}})}catch(e){return Response.json({error:String(e.message||e)},{status:400})}}
 return new Response("Not found",{status:404})
}

export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.pathname.startsWith("/api/ctrader/")) return handleCTrader(request, env);
    if (request.method === "GET" && url.pathname === "/api/manifest.webmanifest") return new Response(JSON.stringify({name:"Analyzer Pro",short_name:"Analyzer Pro",id:"/api/home?appVersion=827",start_url:"/api/home?appVersion=827",scope:"/api/",display:"standalone",orientation:"portrait",background_color:"#08111d",theme_color:"#ff4b55",description:"Analyzer Pro market analysis terminal",icons:[{src:"/api/app-icon.svg",sizes:"192x192 512x512",type:"image/svg+xml",purpose:"any maskable"}]}),{headers:{"Content-Type":"application/manifest+json; charset=utf-8","Cache-Control":"no-store"}});
    if (request.method === "GET" && url.pathname === "/api/app-icon.svg") return new Response('<svg xmlns="http://www.w3.org/2000/svg" width="512" height="512" viewBox="0 0 512 512"><rect width="512" height="512" rx="110" fill="#08111d"/><rect x="34" y="34" width="444" height="444" rx="94" fill="#192638" stroke="#ff4b55" stroke-width="18"/><path d="M125 340 225 150l60 120 105-145" fill="none" stroke="#ff4b55" stroke-width="36" stroke-linecap="round" stroke-linejoin="round"/><circle cx="390" cy="125" r="30" fill="#ff4b55"/></svg>',{headers:{"Content-Type":"image/svg+xml","Cache-Control":"public, max-age=86400"}});
    if (request.method === "GET" && url.pathname === "/api/service-worker.js") return new Response('self.addEventListener("install",e=>{self.skipWaiting()});self.addEventListener("activate",e=>{e.waitUntil(self.clients.claim())});self.addEventListener("fetch",e=>{if(e.request.method!=="GET")return;const u=new URL(e.request.url);if(u.origin!==self.location.origin||u.pathname.startsWith("/api/"))return;e.respondWith(fetch(e.request).catch(()=>caches.match(e.request)))})',{headers:{"Content-Type":"application/javascript; charset=utf-8","Cache-Control":"no-cache","Service-Worker-Allowed":"/api/"}});
    if (url.pathname === "/api/home" && request.method === "GET") return new Response(APP_HTML, { status: 200, headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" } });
    if (url.pathname === "/api/calendar" && request.method === "GET") return handleCalendar();
    if (url.pathname === "/api/market-candles" && request.method === "GET") return handleMarketCandles(request);
    if (url.pathname === "/api/mt5/signals" && request.method === "GET") return handleMT5Signals();
    if (url.pathname === "/api/mt5/signals" && request.method === "GET") return handleMT5Signals();
    if (url.pathname === "/api/candles" && request.method === "GET") return handleCandles(request);
    if (url.pathname === "/api/signals" && request.method === "GET") return handleSignals();
    if (url.pathname === "/api/analyze") return handleAnalyze(request, env);
    if (url.pathname === "/api/chat") return handleChat(request, env);
    if (url.pathname === "/api/execute-trade") return handleExecuteTrade(request, env);
    if (request.method === "GET" && (url.pathname === "/" || url.pathname === "/index.html")) return Response.redirect(new URL("/api/home?appVersion=827", url.origin).toString(), 302);
    const assetResponse = await env.ASSETS.fetch(request);
    if (request.method === "GET" && (url.pathname === "/" || url.pathname.endsWith(".html"))) {
      const headers = new Headers(assetResponse.headers);
      headers.set("Cache-Control", "no-store, max-age=0, must-revalidate");
      return new Response(assetResponse.body, { status: assetResponse.status, statusText: assetResponse.statusText, headers });
    }
    return assetResponse;
  }
};

// Deployment trigger: publish the already-committed SMC progress correction.
